                    else:
                        # no interior colour – should not happen in the task
                        interior_fill = border_colour

                    area = height * width
                    if best is None or area > best[0]:
                        best = (area, border_colour, min_r, max_r, min_c, max_c, interior_fill)

    # unpack best candidate
    area, border_colour, min_r, max_r, min_c, max_c, interior_fill = best
    height = max_r - min_r + 1
    width = max_c - min_c + 1

    # build output grid
    out = [[0] * width for _ in range(height)]

    # fill border with interior colour
    for i in range(height):
        out[i][0] = interior_fill
        out[i][width - 1] = interior_fill
    for j in range(width):
        out[0][j] = interior_fill
        out[height - 1][j] = interior_fill

    # copy interior coloured cells
    for rr in range(min_r + 1, max_r):
        for cc in range(min_c + 1, max_c):
            v = grid[rr][cc]
            if v != 0 and v != border_colour:
                out[rr - min_r][cc - min_c] = v

